-- Preset targets and the fields they need: sample rate, bit depth, encoder preset, frame-rate cap, chapters.
ALTER TABLE quality_target ADD COLUMN label TEXT NOT NULL DEFAULT '';
ALTER TABLE quality_target ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE quality_target ADD COLUMN sample_rate_hz INTEGER;
ALTER TABLE quality_target ADD COLUMN bit_depth INTEGER;
ALTER TABLE quality_target ADD COLUMN encoder_preset TEXT NOT NULL DEFAULT '';
ALTER TABLE quality_target ADD COLUMN max_frame_rate REAL;
ALTER TABLE quality_target ADD COLUMN chapters INTEGER NOT NULL DEFAULT 0 CHECK (chapters IN (0, 1));
ALTER TABLE quality_target ADD COLUMN builtin INTEGER NOT NULL DEFAULT 0 CHECK (builtin IN (0, 1));

